select jsonb_build_object('functions',(select jsonb_agg(t order by t.schema,t.name,t.args) from (select n.nspname as schema,p.proname as name,pg_get_function_identity_arguments(p.oid) as args,md5(p.prosrc) as md5 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','app_private') and (p.proname like 'meal_plan%' or p.proname='has_platform_permission'))t),'policies',(select jsonb_agg(t order by t.policyname) from (select policyname,cmd,qual,with_check from pg_policies where schemaname='public' and tablename='meal_plans')t),'rls',(select relrowsecurity and relforcerowsecurity from pg_class where oid='public.meal_plans'::regclass)) as proof;
